-- Header
local function makeHeader(parent, text, iconAssetId, yPos)
    local container = Instance.new("Frame")
    container.Size = UDim2.new(1, -20, 0, 28)
    container.Position = UDim2.new(0, 10, 0, yPos or 10)
    container.BackgroundTransparency = 1
    container.ZIndex = 14
    container.Parent = parent

    local textOffset = 0
    if iconAssetId and iconAssetId:find("rbxassetid://") then
        local icon = Instance.new("ImageLabel")
        icon.Size = UDim2.new(0, 14, 0, 14)
        icon.Position = UDim2.new(0, 0, 0.5, -7)
        icon.BackgroundTransparency = 1
        icon.Image = iconAssetId
        icon.ImageColor3 = T.Accent1
        icon.ZIndex = 14
        icon.Parent = container
        textOffset = 20
    end

    local h = Instance.new("TextLabel")
    h.Size = UDim2.new(1, -textOffset, 1, 0)
    h.Position = UDim2.new(0, textOffset, 0, 0)
    h.BackgroundTransparency = 1
    h.Text = text
    h.TextColor3 = T.Accent1
    h.TextSize = 14
    h.Font = Enum.Font.GothamBlack
    h.TextXAlignment = Enum.TextXAlignment.Left
    h.ZIndex = 14
    h.Parent = container
    return container
end
-- Close button helper
local function makeClose(parent)
    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(0, 22, 0, 22)
    btn.Position = UDim2.new(1, -30, 0, 12)
    btn.BackgroundColor3 = T.Error
    btn.BackgroundTransparency = 0.85
    btn.Text = ""
    btn.ZIndex = 15
    btn.AutoButtonColor = false
    btn.Parent = parent
    corner(btn, 6)
    
    local icon = Instance.new("ImageLabel")
    icon.Size = UDim2.new(0, 10, 0, 10)
    icon.Position = UDim2.new(0.5, -5, 0.5, -5)
    icon.BackgroundTransparency = 1
    icon.Image = "rbxassetid://116396312853810" -- x
    icon.ImageColor3 = T.Grey
    icon.ZIndex = 15
    icon.Parent = btn

    btn.MouseEnter:Connect(function()
        tween(btn, {BackgroundTransparency = 0.4}, 0.15)
        tween(icon, {ImageColor3 = T.Error}, 0.15)
