local function minimizeUI()
    if not blurEffect then return end -- If already closed
    -- Animate out main UI
    tween(mainFrame, {Position = UDim2.new(0.5, -267.5, 0.65, -250)}, 0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
    tween(bgOverlay, {BackgroundTransparency = 1}, 0.4)
    tween(blurEffect, {Size = 0}, 0.4)
    -- Show cloud
    cloudBtn.Visible = true
    tween(cloudBtn, {Position = UDim2.new(0.5, -25, 0, 20)}, 0.6, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
end
cloudBtn.MouseButton1Click:Connect(function()
    -- Hide cloud
    tween(cloudBtn, {Position = UDim2.new(0.5, -25, 0, -60)}, 0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
    task.delay(0.4, function() cloudBtn.Visible = false end)
    -- Restore main UI
    tween(bgOverlay, {BackgroundTransparency = 0.5}, 0.5)
    if blurEffect then
        tween(blurEffect, {Size = 25}, 0.5)
    end
    tween(mainFrame, {Position = UDim2.new(0.5, -267.5, 0.5, -250)}, 0.6, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
end)
leftMin.MouseButton1Click:Connect(minimizeUI)
-- Close buttons
local function closeUI()
    if getgenv().UI_CLOSING then return end
    getgenv().UI_CLOSING = true
    -- Immediately remove blur so game doesn't stay blurry
    pcall(function() blurEffect.Size = 0 end)
    pcall(function() blurEffect:Destroy() end)
    blurEffect = nil
    -- Animate out
    tween(mainFrame, {Position = UDim2.new(0.5, -267.5, 0.6, -250)}, 0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
    tween(bgOverlay, {BackgroundTransparency = 1}, 0.3)
    task.wait(0.35)
    if Screen then Screen:Destroy() end
    getgenv().UI_CLOSED = true
end
leftClose.MouseButton1Click:Connect(closeUI)
