local isValidating = false
redeemBtn.MouseButton1Click:Connect(function()
    if isValidating then return end
    local key = keyInput.Text:gsub("%s+", "")
    local normalizedKey = key:upper()
    if key == "" then
        statusMsg.Text = "⚠ Please enter a key first"
        tween(statusMsg, {TextColor3 = T.Error}, 0.2)
        local orig = inputBg.Position
        for j = 1, 4 do
            tween(inputBg, {Position = UDim2.new(orig.X.Scale, orig.X.Offset + 8, orig.Y.Scale, orig.Y.Offset)}, 0.04)
            task.wait(0.04)
            tween(inputBg, {Position = UDim2.new(orig.X.Scale, orig.X.Offset - 8, orig.Y.Scale, orig.Y.Offset)}, 0.04)
            task.wait(0.04)
        end
        tween(inputBg, {Position = orig}, 0.08)
        return
    end
    isValidating = true
    statusMsg.Text = "⏳ Validating key..."
    tween(statusMsg, {TextColor3 = T.Warning}, 0.2)
    for _, d in pairs(redeemBtn:GetDescendants()) do
        if d:IsA("TextLabel") then d.Text = "⏳ Checking..." end
    end
    task.spawn(function()
        local isValid = false
        local tier = "none"
        local errMsg = "Invalid Key"
        -- utf8.char(0x2500) .. utf8.char(0x2500) FREE-SERVICE VALIDATION utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500)
        -- Validate against the single free service (19097).
        -- utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)
        -- KEY FIX: Free-first validation with service_id confirmation.
        -- Free keys belong to service #19097 ("snowy free hub").
        -- Premium keys belong to service #16550 ("snowy hub").
        -- The hub validates against 19097, so we check free service FIRST.
        -- A free key will ALWAYS fail the premium service check.
        --
        -- NEW LOGIC:
        -- 1. Validate against free service (19097) first.
        -- 2. If that passes, check response service_id to confirm tier.
        -- 3. If free service fails, try premium service (16550).
        -- 4. If both fail, fall back to key-prefix detection.
        local FREE_SERVICE_ID = "19097"
        local PREM_SERVICE_ID = "16550"

        local function resolveTier(res, fallbackTier)
            if type(res) == "table" and res.service_id then
                local sid = tostring(res.service_id)
                if sid == PREM_SERVICE_ID then return "premium" end
                if sid == FREE_SERVICE_ID then return "free" end
            end
            if type(res) == "table" and type(res.is_premium) == "boolean" then
                return res.is_premium and "premium" or "free"
            end
            return fallbackTier
        end

        -- Step 1: Validate against free service (the hub's service)
        pcall(function()
            Junkie.service    = "snowy free hub"
            Junkie.identifier = JNKIE_USER_ID
            Junkie.provider   = "Mixed"
        end)
        local okFree, resFree = pcall(function() return Junkie.check_key(key) end)
        local checkResult = resFree

        if okFree and type(resFree) == "table" and resFree.valid then
            -- Key validated on free service — check response for service_id
            isValid = true
            tier = resolveTier(resFree, "free")
            checkResult = resFree
        else
            -- Step 2: Free service failed — try premium service
            pcall(function()
                Junkie.service    = "snowy hub"
                Junkie.identifier = JNKIE_USER_ID
                Junkie.provider   = "Mixed"
            end)
            local okPrem, resPrem = pcall(function() return Junkie.check_key(key) end)
            checkResult = resPrem or resFree

            if okPrem and type(resPrem) == "table" and resPrem.valid then
                -- Key validated on premium service
                isValid = true
                tier = resolveTier(resPrem, "premium")
                checkResult = resPrem
            else
                -- Step 3: Both failed — check for HTTP error fallback
                local isHttpError = false
                if (type(resFree) == "table" and (resFree.error == "http 500" or resFree.error == "ERROR")) or
                   (type(resPrem) == "table" and (resPrem.error == "http 500" or resPrem.error == "ERROR")) then
                    isHttpError = true
                end

                if isHttpError then
                    isValid = true
                    tier = resolveTier(resFree or resPrem, detectKeyType(key))
                    warn("[SnowyHub] JNKIE API returned 500/error. Local fallback authenticated.")
                else
                    isValid = false
                end
            end
        end
        if not isValid then
            if type(checkResult) == "table" then
                errMsg = checkResult.error or checkResult.message or errMsg
            elseif type(checkResult) == "string" then
                errMsg = checkResult
            end
            -- Normalize backend messages for the UI
            if errMsg == "KEY_INVALID" then
                errMsg = "Invalid Key"
            elseif errMsg == "KEY_EXPIRED" then
                errMsg = "Key expired — get a new one"
            elseif errMsg == "HWID_BANNED" then
                errMsg = "Hardware banned"
            elseif errMsg == "ALREADY_USED" then
                errMsg = "One-time key already used"
            elseif errMsg == "HWID_MISMATCH" then
                errMsg = "HWID limit reached"
            elseif errMsg == "SERVICE_NOT_FOUND" then
                errMsg = "Service not found — check Jnkie config"
            elseif errMsg == "SERVICE_MISMATCH" then
                errMsg = "Key is for a different service"
            elseif errMsg == "PREMIUM_REQUIRED" then
                errMsg = "Premium key required"
            end
        end
        local tierColor = T.Success
        local overlayBg = Color3.fromRGB(4, 20, 10)
        local flashColor = Color3.fromRGB(0, 200, 100)
        local overlayGrad1 = Color3.fromRGB(0, 35, 20)
        local overlayGrad2 = Color3.fromRGB(0, 20, 8)
        local tierLabel = "FREE ACCESS"
        local tierSub = "Free Tier — Limited Features"
        local tierIcon = "rbxassetid://87706885156127" -- gift
        if tier == "free" then
            getgenv().KEY_TIER = "free"
            getgenv().JD_IS_PREMIUM = false
        elseif tier == "premium" then
            getgenv().KEY_TIER = "premium"
            getgenv().JD_IS_PREMIUM = true
            tierColor = T.Accent1
            overlayBg  = Color3.fromRGB(6, 10, 22)
            flashColor = T.Neon
            overlayGrad1 = Color3.fromRGB(15, 30, 60)
            overlayGrad2 = Color3.fromRGB(8, 15, 30)
            tierLabel  = "PREMIUM ACCESS"
            tierSub    = "Premium Tier — All unlocked"
            tierIcon   = "rbxassetid://92253403464658" -- crown
            local gold = Color3.fromRGB(220, 170, 30)
            tween(centerStroke, {Color = gold}, 0.2)
        end
        if isValid then
            -- Success Flow
            statusMsg.Text = "✨ Key authenticated!"
            tween(statusMsg, {TextColor3 = tierColor}, 0.2)
            redeemText.Text = "Success"
            redeemIcon.Image = "rbxassetid://105979545056636" -- check-circle
            tween(inputStroke, {Color = tierColor, Thickness = 2}, 0.2)
            local overlay = Instance.new("Frame")
            overlay.Size = UDim2.new(1, 0, 1, 0)
            overlay.BackgroundColor3 = overlayBg
            overlay.BackgroundTransparency = 1
            overlay.BorderSizePixel = 0
            overlay.ZIndex = 50
            overlay.Parent = centerPanel
            corner(overlay, 18)
            gradient(overlay, overlayGrad1, overlayGrad2, 110)
            local checkIcon = Instance.new("ImageLabel")
            checkIcon.Size = UDim2.new(0, 10, 0, 10)
            checkIcon.Position = UDim2.new(0.5, -5, 0.45, -5)
            checkIcon.BackgroundTransparency = 1
            checkIcon.Image = tierIcon
            checkIcon.ImageColor3 = tierColor
            checkIcon.ZIndex = 52
            checkIcon.Parent = overlay
            local ring = Instance.new("UIStroke")
            ring.Color = tierColor
            ring.Thickness = 4
            ring.Transparency = 1
            ring.Parent = checkIcon
            corner(checkIcon, 40)
            local sTxt = Instance.new("TextLabel")
            sTxt.Size = UDim2.new(1, 0, 0, 30)
            sTxt.Position = UDim2.new(0, 0, 0.45, 60)
            sTxt.BackgroundTransparency = 1
            sTxt.Text = tierLabel
            sTxt.TextTransparency = 1
            sTxt.TextColor3 = T.White
            sTxt.TextSize = 22
            sTxt.Font = Enum.Font.GothamBlack
            sTxt.ZIndex = 52
            sTxt.Parent = overlay
            local dTxt = Instance.new("TextLabel")
            dTxt.Size = UDim2.new(1, 0, 0, 20)
            dTxt.Position = UDim2.new(0, 0, 0.45, 95)
            dTxt.BackgroundTransparency = 1
            dTxt.Text = tierSub
            dTxt.TextTransparency = 1
            dTxt.TextColor3 = T.Grey
            dTxt.TextSize = 14
            dTxt.Font = Enum.Font.GothamMedium
            dTxt.ZIndex = 52
            dTxt.Parent = overlay
            local flash = Instance.new("Frame")
            flash.Size = UDim2.new(1, 0, 1, 0)
            flash.BackgroundColor3 = flashColor
            flash.BackgroundTransparency = 1
            flash.BorderSizePixel = 0
            flash.ZIndex = 60
            flash.Parent = centerPanel
            corner(flash, 18)
            tween(flash, {BackgroundTransparency = 0.5}, 0.1)
            task.wait(0.12)
            tween(flash, {BackgroundTransparency = 1}, 0.3)
            task.delay(0.5, function() flash:Destroy() end)
            tween(overlay, {BackgroundTransparency = 0.15}, 0.25)
            tween(checkIcon, {Size = UDim2.new(0, 75, 0, 75), Position = UDim2.new(0.5, -37.5, 0.45, -37.5)}, 0.4, Enum.EasingStyle.Elastic)
            tween(ring, {Transparency = 0}, 0.2)
            task.wait(0.15)
            tween(sTxt, {TextTransparency = 0, Position = UDim2.new(0, 0, 0.45, 50)}, 0.25, Enum.EasingStyle.Back)
            tween(dTxt, {TextTransparency = 0, Position = UDim2.new(0, 0, 0.45, 80)}, 0.25, Enum.EasingStyle.Back)
            -- utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) PERF FIX: cut cosmetic delay 2s -> 0.4s utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)
            -- Total post-validate delay was ~1.95s of pure cosmetic waits
            -- on top of the 3-5s hub compile freeze. Cut to 0.4s so the
            -- user gets to the loading overlay (and hub) much faster.
            task.wait(0.4)
            -- NUCLEAR KEY SET: Broadcast to all levels of memory
            local function broadcast(k, v)
                getgenv()[k] = v
            end
            -- utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) PERF FIX: Kill per-frame animation loop + blur BEFORE loading the hub utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500)
            -- The master Heartbeat runs at 60Hz touching ~12 UI instances; leaving it
            -- alive while the 18k-line hub synchronously builds its UI freezes the game
            -- to 0 FPS. Destroy all heavy UI *before* broadcasting SCRIPT_KEY (which
            -- releases the outer `while not SCRIPT_KEY` loop and triggers hub load).
            pcall(function() if masterConn then masterConn:Disconnect(); masterConn = nil end end)
            pcall(function() if blurEffect then blurEffect.Size = 0; blurEffect:Destroy(); blurEffect = nil end end)
            pcall(function() if Screen and Screen.Parent then Screen:Destroy() end end)
            getgenv().UI_CLOSING = true
            getgenv().UI_CLOSED  = true
            -- utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) PERF FIX: Persistent "Loading Hub..." overlay utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)utf8.char(0x2500) .. utf8.char(0x2500)
            -- The hub script is ~700KB and takes 3-5s to HttpGet + loadstring
            -- + synchronously build its UI. Without this overlay the user
            -- sees a frozen black screen for that entire window. We park a
            -- minimal lightweight ScreenGui in CoreGui that survives the
            -- UI destroy, and the hub script destroys it via
            -- getgenv().__SnowyLoadingOverlay:Destroy() when its UI is ready.
            -- A 60s safety timeout removes it if the hub never signals.
            local loadingOk, loadingScreen = pcall(function()
                local sg = Instance.new("ScreenGui")
                sg.Name = game:GetService("HttpService"):GenerateGUID(false):sub(1, 8)
                sg.IgnoreGuiInset = true
